if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

const allSlugs = [];
const animalsIndex = [];

animals.forEach((animal) => {
  const data = {
    slug: animal.slug,
    displayName: animal.name,
    icon: animal.icon,
    description: animal.description,
    metaDescription: `Discover the perfect name for your ${animal.name.toLowerCase()} ${animal.icon}! Browse 100 male, female, cute, funny, and fantasy names with our free animal name generator.`,
    maleNames: pickRandom(namePools.male, 20),
    femaleNames: pickRandom(namePools.female, 20),
    cuteNames: pickRandom(namePools.cute, 20),
    funnyNames: pickRandom(namePools.funny, 20),
    fantasyNames: pickRandom(namePools.fantasy, 20),
    uniqueNames: pickRandom(namePools.unique, 20),
    coolNames: pickRandom(namePools.cool, 20),
    babyNames: pickRandom(namePools.baby, 20),
    faq: faqTemplates(animal.name, animal.icon),
    seoTitle: `${animal.name} Name Generator - 100+ ${animal.name} Name Ideas ${animal.icon}`,
    seoDescription: `Find the perfect ${animal.name.toLowerCase()} name! Browse 100+ male, female, cute, funny, and fantasy ${animal.name.toLowerCase()} names ${animal.icon}. Free animal name generator with unique ideas.`,
    namingGuide: [
      `Consider your ${animal.name.toLowerCase()}'s personality — is it bold, shy, playful, or calm?`,
      `Look at physical traits like color, size, or unique markings.`,
      `Say the name out loud — does it sound natural and easy to call?`,
      `Avoid names that sound like common commands or other pets' names.`,
      `Try out a few names and see which one your ${animal.name.toLowerCase()} responds to best.`,
      `Short names (1-2 syllables) tend to be easiest for animals to learn and recognize.`,
    ],
  };

  const filePath = path.join(DATA_DIR, `${animal.slug}.json`);
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
  allSlugs.push(animal.slug);
  animalsIndex.push({ slug: animal.slug, name: animal.name, icon: animal.icon });
});

fs.writeFileSync(
  path.join(DATA_DIR, "index.json"),
  JSON.stringify(animalsIndex, null, 2)
);

console.log(`✅ Generated ${animals.length} animal data files!`);
